---Indentation for Jason agent programs and mas2j project files.
---
---The style follows the templates generated by `jason app create`:
---
---  +!start : true
---      <- .print("hello");
---         !next.
---
---  +!loop
---      :   ready
---      <-  while (busy) {
---              .wait(100);
---          }
---          !loop.
local M = {}

---@param lnum integer
---@return string line without trailing comments and whitespace
local function code(lnum)
  local line = vim.fn.getline(lnum)
  line = line:gsub("//.*$", ""):gsub("/%*.-%*/", "")
  return (line:gsub("%s+$", ""))
end

---@param lnum integer
---@return integer previous line that has code, 0 if none
local function prev_code_line(lnum)
  local p = vim.fn.prevnonblank(lnum - 1)
  while p > 0 do
    local text = code(p)
    if text ~= "" and not text:match("^%s*%*") and not text:match("^%s*/%*") then
      return p
    end
    p = vim.fn.prevnonblank(p - 1)
  end
  return 0
end

local ts_skip = { comment = true, string = true, escape_sequence = true, quoted_atom = true }

---Whether (lnum, col), 1-based, is inside a comment, string or quoted atom.
---Uses the tree-sitter tree when tree-sitter highlights the buffer (the
---Vim syntax is off then), else the syntax file.
---@param lnum integer
---@param col integer
---@return boolean
local function in_string_or_comment(lnum, col)
  local buf = vim.api.nvim_get_current_buf()
  if vim.treesitter.highlighter.active[buf] then
    local ok, node = pcall(vim.treesitter.get_node, { bufnr = buf, pos = { lnum - 1, col - 1 }, ignore_injections = true })
    return ok and node ~= nil and ts_skip[node:type()] == true
  end
  local name = vim.fn.synIDattr(vim.fn.synID(lnum, col, 0), "name"):lower()
  return name:find("comment") ~= nil or name:find("string") ~= nil or name:find("quotedatom") ~= nil
end

---searchpair() skip callback: ignore brackets in comments and strings.
local function skip()
  return in_string_or_comment(vim.fn.line("."), vim.fn.col("."))
end

---Bring the tree-sitter tree up to date before querying it.
local function refresh_tree()
  local buf = vim.api.nvim_get_current_buf()
  if vim.treesitter.highlighter.active[buf] then
    pcall(function()
      vim.treesitter.get_parser(buf):parse()
    end)
  end
end

---@param lnum integer
---@param open string
---@param close string
---@return integer line of the unmatched opening bracket before lnum, 0 if none
local function enclosing(lnum, open, close)
  return vim.api.nvim_win_call(0, function()
    local view = vim.fn.winsaveview()
    vim.fn.cursor(lnum, 1)
    local found = vim.fn.searchpair(open, "", close, "bW", skip)
    vim.fn.winrestview(view)
    return found
  end)
end

---Column where the statement on a line starts: after `<-` when the line
---holds a plan body, else the line's indent.
---@param lnum integer
---@return integer
local function stmt_col(lnum)
  local body = code(lnum):match("^(.-<%-%s*)%S")
  if body then
    return vim.fn.strdisplaywidth(body)
  end
  return vim.fn.indent(lnum)
end

---Indentation for a new top-level clause or a clause inside a { } block.
---@param lnum integer
---@return integer
local function clause_base(lnum)
  local brace = enclosing(lnum, [[{]], [[}]])
  if brace > 0 then
    return vim.fn.indent(brace) + vim.fn.shiftwidth()
  end
  return 0
end

---@param lnum integer
---@return integer
function M.get(lnum)
  local sw = vim.fn.shiftwidth()
  local cur = vim.fn.getline(lnum)

  refresh_tree()

  -- Inside a block comment: keep the leading ' *' aligned.
  if cur:match("^%s*%*") and in_string_or_comment(lnum, vim.fn.indent(lnum) + 1) then
    return vim.fn.indent(lnum)
  end

  -- Closing brackets line up with the line that opened them.
  local closer = cur:match("^%s*([}%])])")
  if closer then
    local pairs = { ["}"] = { "{", "}" }, [")"] = { "(", ")" }, ["]"] = { "\\[", "\\]" } }
    local open = enclosing(lnum, pairs[closer][1], pairs[closer][2])
    if open > 0 then
      return stmt_col(open)
    end
  end

  local p = prev_code_line(lnum)
  if p == 0 then
    return 0
  end
  local prev = code(p)
  local pind = vim.fn.indent(p)

  -- A clause ended: back to the clause level of the surrounding block.
  if prev:match("%.$") and not prev:match("%.%.$") then
    return clause_base(lnum)
  end

  -- Opened a block or an argument/list on the previous line.
  if prev:match("[{%(%[]$") then
    return stmt_col(p) + sw
  end

  -- `<- body` with more statements: align with the first body formula.
  local body = prev:match("^(.-<%-%s*)%S")
  if body and prev:match(";$") then
    return vim.fn.strdisplaywidth(body)
  end

  -- Context line (`: ctx`) or a trigger without its body yet: indent once
  -- from the trigger; a following `<-` / `:` line stays at that level.
  if cur:match("^%s*<%-") or cur:match("^%s*:[^%-]") then
    if prev:match("^%s*<%-") or prev:match("^%s*:") then
      return pind
    end
    return pind + sw
  end
  local trigger = prev:match("^%s*[%+%-%^]") or prev:match("^%s*@%S*%s+[%+%-%^]")
  if trigger and not prev:match(";$") then
    return pind + sw
  end
  -- `head :-` / `... <-` / `... :` with the rest on the next line.
  if prev:match("<%-$") or prev:match(":%-$") or prev:match(":$") then
    return pind + sw
  end

  return pind
end

---@param lnum integer
---@return integer
function M.get_mas2j(lnum)
  refresh_tree()
  local cur = vim.fn.getline(lnum)
  local closer = cur:match("^%s*([}%]])")
  if closer then
    local open = closer == "}" and enclosing(lnum, [[{]], [[}]]) or enclosing(lnum, "\\[", "\\]")
    if open > 0 then
      return vim.fn.indent(open)
    end
  end
  local p = prev_code_line(lnum)
  if p == 0 then
    return 0
  end
  local prev = code(p)
  -- Section headers (`agents:`, `aslSourcePath:`) sit one level inside MAS { }.
  if cur:match("^%s*%a+:") then
    local brace = enclosing(lnum, [[{]], [[}]])
    return brace > 0 and vim.fn.indent(brace) + vim.fn.shiftwidth() or 0
  end
  if prev:match("[{%[]$") then
    return vim.fn.indent(p) + vim.fn.shiftwidth()
  end
  -- `agents: bob;` continues with `alice;` aligned under `bob`.
  local section = prev:match("^(%s*%a+:%s*)%S.*;$")
  if section then
    return vim.fn.strdisplaywidth(section)
  end
  return vim.fn.indent(p)
end

return M
